# --------------------------------------------------------------------------------------
# 2. available_at
# --------------------------------------------------------------------------------------

def available_at(release_date: str, clock: str = "08:30", tz: str = ET) -> pd.Timestamp:
    """The instant a number exists, as a tz-aware UTC timestamp.

    Localise in the AGENCY's timezone and convert once. Never store a naive timestamp and
    never hardcode a UTC offset: the offset for 08:30 ET is -5 in winter and -4 in summer.
    """
    naive = pd.Timestamp(f"{release_date} {clock}")
    return naive.tz_localize(tz).tz_convert("UTC")


def dst_audit(dates: list[str], clock: str = "08:30", tz: str = ET) -> dict:
    """How a fixed UTC offset misprices a fixed local release time over a year."""
    ts = [pd.Timestamp(f"{d} {clock}").tz_localize(tz) for d in dates]
    offs = pd.Series([t.utcoffset().total_seconds() / 3600 for t in ts], index=dates)
    fixed = offs.mode().iloc[0]
    wrong = offs != fixed
    return {"offsets": offs.value_counts().to_dict(), "modal_offset": float(fixed),
            "n_wrong_if_hardcoded": int(wrong.sum()), "n": len(dates),
            "error_hours": float((offs[wrong] - fixed).abs().max()) if wrong.any() else 0.0}


def payroll_release_dates(start: str = "2017-01", end: str = "2022-12") -> pd.DataFrame:
    """First Friday of each month - BLS's usual Employment Situation day, at 08:30 ET.

    'Usually' is doing real work here: BLS shifts the date around holidays and the annual
    benchmark. Treat this as a stand-in and use the published schedule for anything live.
    """
    rows = []
    for p in pd.period_range(start, end, freq="M"):
        ref = p - 1                                 # January's report lands in February
        first = pd.Timestamp(year=p.year, month=p.month, day=1)
        rel = first + pd.Timedelta(days=(4 - first.dayofweek) % 7)
        rows.append({"ref_period": ref, "ref_start": ref.start_time,
                     "ref_end": ref.end_time.normalize(), "release_date": rel,
                     "available_at": available_at(rel.strftime("%Y-%m-%d"), "08:30")})
    return pd.DataFrame(rows)


