# 3. The holiday-shift audit
# --------------------------------------------------------------------------------------

def shift_audit(shifts, nominal_day: str, nominal_clock: str) -> dict:
    """How far EIA's own published exceptions sit from the rule everyone hardcodes."""
    rows = []
    for d, printed_day, clock in shifts:
        ts = pd.Timestamp(d)
        assert ts.day_name() == printed_day, (d, ts.day_name(), printed_day)
        delta = ((pd.Timestamp(f"{d} {clock}") - pd.Timestamp(f"{d} {nominal_clock}"))
                 .total_seconds() / 3600.0)
        rows.append({"date": d, "day": printed_day, "clock": clock,
                     "day_changed": printed_day != nominal_day, "hours_late": delta})
    tab = pd.DataFrame(rows)
    return {"table": tab, "n": len(tab), "n_day_changed": int(tab["day_changed"].sum()),
            "max_hours_late": float(tab["hours_late"].max()),
            "distinct_clocks": sorted(set(tab["clock"]) | {nominal_clock})}


# --------------------------------------------------------------------------------------
# 4. The as-of join
# --------------------------------------------------------------------------------------

STAMPS = ("reference period start", "reference period end", "release date midnight",
          "release timestamp")


def stamp_series(cal: pd.DataFrame, how: str) -> pd.Series:
    """A monthly macro series indexed by whichever instant the analyst chose."""
    if how == "reference period start":
        idx = cal["ref_start"]
    elif how == "reference period end":
        idx = cal["ref_end"]
    elif how == "release date midnight":
        idx = cal["release_date"]
    elif how == "release timestamp":
        idx = cal["available_at"].dt.tz_convert(ET).dt.tz_localize(None)
    else:
        raise ValueError(how)
    return pd.Series(np.arange(len(cal), dtype=float), index=pd.DatetimeIndex(idx))


def join_audit(cal: pd.DataFrame, bar_clock: str = "09:30") -> pd.DataFrame:
    """For each stamping convention: how often the joined value did not yet exist.

    Decisions are taken at `bar_clock` ET on every weekday in the sample - the equity
    open. The value used is the last one whose stamp is at or before that instant; the
    look-ahead is the gap between the decision instant and that value's true
    `available_at`, and it is positive whenever the value had not been published.
    """
    lo = cal["release_date"].min().normalize()
    hi = cal["release_date"].max().normalize()
    days = pd.bdate_range(lo, hi)
    decide = pd.DatetimeIndex([d + pd.Timedelta(bar_clock + ":00") for d in days])
    truth = pd.Series(cal["available_at"].dt.tz_convert(ET).dt.tz_localize(None).to_numpy(),
                      index=np.arange(len(cal), dtype=float))
    rows = []
    for how in STAMPS:
        s = stamp_series(cal, how).sort_index()
        used = s.reindex(s.index.union(decide)).ffill().reindex(decide)
        ok = used.notna()
        pub = pd.Series(truth.reindex(used[ok].to_numpy()).to_numpy(), index=decide[ok])
        lead = (pub - decide[ok]).dt.total_seconds() / 3600.0     # hours of look-ahead
        bad = lead > 0
        rows.append({"stamp": how, "days": int(ok.sum()),
                     "days_with_lookahead": int(bad.sum()),
                     "share": float(bad.mean()),
                     "mean_hours": float(lead[bad].mean()) if bad.any() else 0.0,
                     "max_hours": float(lead.max()) if bad.any() else 0.0,
                     "mean_days": float(lead[bad].mean() / 24) if bad.any() else 0.0})
    return pd.DataFrame(rows).set_index("stamp")


