LOCKUP_END = pd.Timestamp("2020-06-03")


def capture(latency_ms: float, half_life_ms: float) -> float:
    """Share of the release's total price move already in the price at `latency_ms`.

    Exponential price discovery with a stated half-life. The half-lives are the ONE
    assumption in this script; their ORDERING is what the DOL Inspector General describes
    - lock-up participants pre-loaded the data into machine-readable feeds, so the move
    was in the price before the general public had finished downloading the file.
    """
    return float(1.0 - 2.0 ** (-latency_ms / half_life_ms))


def splice_study(n_events: int = 260, seed: int = SEED, latency_ms: float = 250.0,
                 half_life_pre: float = 40.0, half_life_post: float = 1500.0,
                 assumed_capture: float = 0.50, move_bp: float = 22.0) -> dict:
    """One strategy, one latency, across the 2020-06-03 boundary.

    The strategy reads the print and takes liquidity at `latency_ms`. Its cost is the part
    of the move it has already paid for: `capture` x move. A backtest that assumes one
    fixed `assumed_capture` across the whole sample is wrong in opposite directions on the
    two sides of the boundary.
    """
    rng = np.random.default_rng(seed)
    dates = pd.date_range("2018-01-05", periods=n_events, freq="7D")
    pre = dates < LOCKUP_END
    surprise = rng.normal(0.0, 1.0, n_events)
    move = move_bp * surprise                                   # bp, signed
    cap = np.where(pre, capture(latency_ms, half_life_pre),
                   capture(latency_ms, half_life_post))
    edge_true = np.abs(move) * (1.0 - cap)
    edge_assumed = np.abs(move) * (1.0 - assumed_capture)
    return {
        "n_pre": int(pre.sum()), "n_post": int((~pre).sum()),
        "capture_pre": capture(latency_ms, half_life_pre),
        "capture_post": capture(latency_ms, half_life_post),
        "edge_true_pre": float(edge_true[pre].mean()),
        "edge_true_post": float(edge_true[~pre].mean()),
        "edge_assumed": float(edge_assumed.mean()),
        "err_pre": float((edge_assumed[pre] - edge_true[pre]).mean()),
        "err_post": float((edge_assumed[~pre] - edge_true[~pre]).mean()),
        "err_full": float((edge_assumed - edge_true).mean()),
        "latency_ms": latency_ms,
    }


def latency_grid(latencies=(10, 50, 250, 1000, 5000), half_life_pre: float = 40.0,
                 half_life_post: float = 1500.0) -> pd.DataFrame:
    return pd.DataFrame({
        "latency_ms": list(latencies),
        "captured_pre_2020": [capture(x, half_life_pre) for x in latencies],
        "captured_post_2020": [capture(x, half_life_post) for x in latencies],
    }).set_index("latency_ms")


